import{_ as r,l as p,o as e,c as n,v as o,p as i,x as t,d as s,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"交叉熵与极大似然","description":"","frontmatter":{"title":"交叉熵与极大似然","date":"2026-09-10T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cross-entropy-mle.md","filePath":"llm/cross-entropy-mle.md","lastUpdated":1789023840000}'),d={name:"llm/cross-entropy-mle.md"};function _(c,a,f,u,E,x){const l=p("Mermaid");return e(),n("div",null,[a[1]||(a[1]=o('<h1 id="交叉熵与极大似然" tabindex="-1">交叉熵与极大似然 <a class="header-anchor" href="#交叉熵与极大似然" aria-label="Permalink to &quot;交叉熵与极大似然&quot;">​</a></h1><div class="epigraph"><p>把模型的 softmax 输出当成类别分布，最小化交叉熵就是在做极大似然；标签的 one-hot 只是这条似然的写法。</p><footer>—— 据 Goodfellow, Bengio &amp; Courville, Deep Learning, 2016；Shannon, A Mathematical Theory of Communication, 1948 整理</footer></div><p><a href="/llm/softmax-numerics">Softmax 与数值稳定</a>把分数变成 \\(p\\)。本课不重写减最大值。缺口是：有了 \\(p\\)，如何给一次预测打一个可反传的标量损失。分类里这个标量是交叉熵，它与「标签类别的对数似然」是同一件事。本课只钉住这一等价，不展开下一词的时间展开，那是两课之后。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(p\\) 落在单纯形上，仍可以离标签很远。需要一个损失，在 \\(p\\) 把质量都分给正确类时接近 \\(0\\)，在分给错误类时变大，并且对 \\(z\\) 可微。平方误差也能做，但它惩罚的是概率值本身，不直接对应「生成这条标签的概率」。统计上，若把标签视为从未知分布抽样，一次观测的似然就是 \\(p_y\\)。缺口是把 \\(-\\log p_y\\) 写成训练目标，并承认它就是交叉熵。</p><p>对经验分布 \\(\\hat q\\)（正确类为 \\(1\\)，其余为 \\(0\\)），交叉熵 \\(H(\\hat q,p)=-\\sum_k \\hat q_k\\log p_k\\) 只剩 \\(-\\log p_y\\)。KL 散度 \\(D_{\\mathrm{KL}}(\\hat q\\|p)=H(\\hat q,p)-H(\\hat q)\\)，而 one-hot 的熵为 \\(0\\)，故最小化交叉熵与最小化 KL 在分类里重合。本课不把 KL 当成另一门课的主角，只用来说明：我们不是在拟合分数，而是在拟合分布。</p><h3 id="交叉熵不是「概率差的绝对值」" tabindex="-1">交叉熵不是「概率差的绝对值」 <a class="header-anchor" href="#交叉熵不是「概率差的绝对值」" aria-label="Permalink to &quot;交叉熵不是「概率差的绝对值」&quot;">​</a></h3><p>\\(|1-p_y|\\) 在 \\(p_y\\) 已经是 \\(0.9\\) 时很小，但 \\(-\\log p_y\\) 仍在逼模型把质量继续堆到正确类上。更重要的是梯度：对 softmax 接交叉熵，\\(\\partial L/\\partial z=p-y\\)，错误类只要还有质量就会被往下推。改用 MAE 或 MSE 接在 softmax 后，梯度会被 \\(p(1-p)\\) 一类因子再压一层，饱和更严重。后课默认分类头接的是交叉熵，不是回归损失。</p><p><span class="marginnote">标签可以是 soft label，例如蒸馏里的教师分布。那时 \\(H(q,p)=-\\sum_k q_k\\log p_k\\) 不再退化成单项。本课的默认仍是 one-hot；软标签不改变「交叉熵 \\(=\\) 负对数似然」这条，只是似然换成了教师的。 </span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给定分数 \\(z\\)、稳定 softmax 得到 \\(p\\)，整数标签 \\(y\\in\\{0,\\ldots,K-1\\}\\)，</p> \\[L=-\\log p_y= -z_y+\\log\\sum_k\\mathrm{e}^{z_k}. \\]<p>右端是 \\(\\mathrm{logsumexp}\\) 写法，下一课专门处理它的 underflow。形状上，\\(L\\) 对每个样本一个标量，再对批求平均。\\(y\\) 必须落在 \\(0\\ldots K-1\\)；越界不是 UNK，是标签协议错了。类别不平衡时可以对 \\(L\\) 按类加权，那是数据课的事，不改本课的定义。</p><p>与 logits 的梯度 \\(\\partial L/\\partial z=p-e_y\\) 应记住：正确类分量是 \\(p_y-1\\le 0\\)，其余是 \\(p_k\\ge 0\\)。无需再把 softmax 的 Jacobian 显式乘一遍。这是后课反向传播里「损失对最后一层的局部导数」的具体实例。</p>',14)),(e(),i(h,null,{default:t(()=>[m(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E5%88%86%E6%95%B0%20z%22%5D%20--%3E%20SM%5B%22%E7%A8%B3%E5%AE%9A%20softmax%22%5D%0A%20%20SM%20--%3E%20P%5B%22%E5%88%86%E5%B8%83%20p%22%5D%0A%20%20Y%5B%22%E6%A0%87%E7%AD%BE%20y%22%5D%20--%3E%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20P%20--%3E%20CE%0A%20%20CE%20--%3E%20L%5B%22%E6%A0%87%E9%87%8F%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>极大似然把「模型认为该标签有多可能」变成可加的目标：独立样本的联合似然是乘积，取负对数变成求和。这与信息论里用 \\(-\\log p\\) 度量「惊讶」一致：模型越意外，损失越大。平均交叉熵的单位是 nat（自然对数）或 bit（以 \\(2\\) 为底）；比较不同实验时底要一致，否则「损失从 \\(2.1\\) 降到 \\(1.8\\)」不可比。</p><p>因为 \\(L\\) 只通过 \\(p_y\\) 依赖正确类，错误类之间如何分剩余质量，在 one-hot 监督下不受直接约束。模型可以把剩余质量均匀摊开，也可以堆到某个相似类上。这不是缺陷，是目标的定义：我们只要求正确类的质量尽量大。若需要类间结构，要改标签或改损失，不能指望交叉熵自动学会。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理概率连乘导致的 underflow，那是下一课<a href="/llm/logspace-underflow">对数空间与 underflow</a>。也不把序列上的因式分解写开，那是<a href="/llm/clm-as-next-token">下一词分类</a>。回归、对比损失、强化学习里的策略梯度，都不在本课。后课默认：分类头的训练目标是平均交叉熵，对 logits 的梯度是 \\(p-y\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交叉熵 \\(L=-\\log p_y\\) 即标签的负对数似然；one-hot 下与 KL 只差一个常数 \\(0\\)。</li><li>对 softmax 的梯度是 \\(p-y\\)，不必再乘 Jacobian。</li><li>目标只约束正确类的质量；错误类之间的分配不受直接监督。</li><li>损失的底决定单位，跨实验比较时必须一致。</li><li>出处：Goodfellow et al., Deep Learning, 2016；Shannon, 1948。</li></ul>',7))])}const g=r(d,[["render",_]]);export{A as __pageData,g as default};
